def collapse_ints(nums: list[int]) -> str:
    """See SPEC.md."""
    if not nums:
        return ""
    vals = sorted(set(nums))
    parts: list[str] = []
    i = 0
    n = len(vals)
    while i < n:
        j = i
        while j + 1 < n and vals[j + 1] == vals[j] + 1:
            j += 1
        if j - i + 1 >= 4:
            parts.append(_fmt(vals[i]) + "-" + _fmt(vals[j]))
        else:
            for k in range(i, j + 1):
                parts.append(str(vals[k]))
        i = j + 1
    return ",".join(parts)


def _fmt(x: int) -> str:
    """Format a range endpoint; negatives in parentheses."""
    return f"({x})" if x < 0 else str(x)

